Object\n"},["scripts/items/dish_of_spaghetti_pescatora.lua"]={["Path"]="scripts/items/dish_of_spaghetti_pescatora.lua",["SHA256"]="535c2ac5d8be80508aef41cd62f184d4bc97e248a599eca720c146c351044611",["Text"]="-----------------------------------\n-- ID: 5191\n-- Item: dish_of_spaghetti_pescatora\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health % 15\n-- Health Cap 150\n-- Vitality 3\n-- Mind -1\n-- Defense % 22\n-- Defense Cap 65\n-- Store TP 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 15)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 150)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_DEFP, 22)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 65)\n    effect:addMod(xi.mod.STORETP, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dish_of_spaghetti_pescatora_+1.lua"]={["Path"]="scripts/items/dish_of_spaghetti_pescatora_+1.lua",["SHA256"]="4fe47eb89e970b1b456ea10c62350b52d00722c01056848638fa45ed909962b1",["Text"]="-----------------------------------\n-- ID: 5200\n-- Item: dish_of_spaghetti_pescatora_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health % 15\n-- Health Cap 160\n-- Vitality 3\n-- Mind -1\n-- Defense % 22\n-- Defense Cap 70\n-- Store TP 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 15)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 160)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_DEFP, 22)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 70)\n    effect:addMod(xi.mod.STORETP, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dish_of_spaghetti_tonno_rosso.lua"]={["Path"]="scripts/items/dish_of_spaghetti_tonno_rosso.lua",["SHA256"]="cec73235d513b2da7e7367a538a558ffe6ff4b62663a0f033cac6c368c30b6e0",["Text"]="-----------------------------------\n-- ID: 5623\n-- Item: Dish of Spaghetti Tonno Rosso\n-- Food Effect: 30 Mins, All Races\n-----------------------------------\n-- Health % 13\n-- Health Cap 180\n-- Dexterity 1\n-- Vitality 2\n-- Store TP +6\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 13)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 180)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.STORETP, 6)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dish_of_spaghetti_tonno_rosso_+1.lua"]={["Path"]="scripts/items/dish_of_spaghetti_tonno_rosso_+1.lua",["SHA256"]="27c64123152d7c709facbbfe3b5b18a18966d0c89c18f12f12a14e1e161e5934",["Text"]="-----------------------------------\n-- ID: 5624\n-- Item: Dish of Spaghetti Tonno Rosso +1\n-- Food Effect: 60 Mins, All Races\n-----------------------------------\n-- Health % 13\n-- Health Cap 185\n-- Dexterity 2\n-- Vitality 3\n-- Store TP +6\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 13)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 185)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.STORETP, 6)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dish_of_spaghetti_vongole_rosso.lua"]={["Path"]="scripts/items/dish_of_spaghetti_vongole_rosso.lua",["SHA256"]="27c811277a181d1421e12ded288cd70cfeacaf72bff2173bf2108c49cc4c59a7",["Text"]="-----------------------------------\n-- ID: 5189\n-- Item: dish_of_spaghetti_vongole_rosso\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health % 20\n-- Health Cap 90\n-- Vitality 2\n-- Mind -1\n-- Defense % 25\n-- Defense Cap 30\n-- Store TP 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 20)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 90)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 30)\n    effect:addMod(xi.mod.STORETP, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dispel_couse.lua"]={["Path"]="scripts/items/dispel_couse.lua",["SHA256"]="e6c970dee38708c8fbfe24023fc814b23e3e2fc0561425f7569b498db3843bd0",["Text"]="-----------------------------------\n-- ID: 18095\n-- Item: Dispel Couse\n-- Item Effect: Dispels one beneficial effect from the target\n-- Bypasses Magical Immunity - https://www.youtube.com/watch?v=CuTyCwzQqtY\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local dispelledEffect = target:dispelStatusEffect()\n\n    if dispelledEffect == xi.effect.NONE then\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT)\n        return 0\n    end\n\n    action:messageID(target:getID(), xi.msg.basic.ITEM_EFFECT_DISAPPEARS)\n    return dispelledEffect\nend\n\nreturn itemObject\n"},["scripts/items/divine_bolt_quiver.lua"]={["Path"]="scripts/items/divine_bolt_quiver.lua",["SHA256"]="b3dd16b9cc9a707b24f4c955cb51fd50df9fb968e5a1cbc622471086254eb3a2",["Text"]="-----------------------------------\n-- ID: 6427\n-- Divine Volt Quiver\n-- When used, you will obtain one stack of Divine Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DIVINE_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/divine_bullet_pouch.lua"]={["Path"]="scripts/items/divine_bullet_pouch.lua",["SHA256"]="a4c8afeeb570aad3f26fa248352cecac3af8191843d921ab4a38843603383915",["Text"]="-----------------------------------\n-- ID: 6437\n-- Divine Bullet Pouch\n-- When used, you will obtain one stack of Divine Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DIVINE_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/divine_quiver.lua"]={["Path"]="scripts/items/divine_quiver.lua",["SHA256"]="45d41006a5d57f52588e2746ae5fa37d670c7f98fd5971f785d1903cf0474f92",["Text"]="-----------------------------------\n-- ID: 6417\n-- Divine Quiver\n-- When used, you will obtain one stack of Divine Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DIVINE_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/divine_sword.lua"]={["Path"]="scripts/items/divine_sword.lua",["SHA256"]="20bbd3de463a45f64aa6be153c806e1400b0b4b3b1df5511549e97b28d446045",["Text"]="-----------------------------------\n-- ID: 16549\n-- Item: Divine Sword\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(4, 6),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/divine_sword_+1.lua"]={["Path"]="scripts/items/divine_sword_+1.lua",["SHA256"]="f55a0b7f2307db91aac6477558605cfaada58ee8e51c6461dd2cb3d3d366f34a",["Text"]="-----------------------------------\n-- ID: 17510\n-- Item: Divine Sword +1\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(4, 6),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/dolphin_staff.lua"]={["Path"]="scripts/items/dolphin_staff.lua",["SHA256"]="a6370ea6f71e0085d2b0019537d94d78ae2b24da17801845a8fb4fe68a2d2c04",["Text"]="-----------------------------------\n-- ID: 17134\n-- Item: Dolphin Staff\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 8 + utils.clamp(dStat * 3 / 27, 0, 25), -- 0-8% over 54 dINT, approx.\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/dominus_shield.lua"]={["Path"]="scripts/items/dominus_shield.lua",["SHA256"]="3196653c6148d94835cd57fb76a725cbc236c4843487d6d1476617e0c3193a08",["Text"]="-----------------------------------\n-- ID: 14491\n-- Item: Dominus Shield\n-- Item Effect: Restores 20-35 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local mpHeal = math.randomInt(60, 85)\n    local dif = target:getMaxMP() - target:getMP()\n    if mpHeal > dif then\n        mpHeal = dif\n    end\n\n    target:addMP(mpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, mpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/dragon_claws.lua"]={["Path"]="scripts/items/dragon_claws.lua",["SHA256"]="97409b447e1a6685029a77e15e3e7d26d3974206e921d60b82f18b3e44652933",["Text"]="-----------------------------------\n-- ID: 16416\n-- Item: Dragon Claws\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = 6 + utils.clamp(math.floor(dStat / 1.5), 0, 32) -- Somewhat approximate. It looks like x/256 madness is going on\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(power, power + 3), -- Upper range is sometimes not +5, but this is good enough.\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/dragon_claws_+1.lua"]={["Path"]="scripts/items/dragon_claws_+1.lua",["SHA256"]="06de79b4e77d23a76cbced10553a9a9d21f7df7f3ceef9ef1be6181f699e8737",["Text"]="-----------------------------------\n-- ID: 17485\n-- Item: Dragon Claws +1\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = 9 + utils.clamp(math.floor(dStat / 1.5), 0, 32)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(power, power + 3),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/dragon_fruit.lua"]={["Path"]="scripts/items/dragon_fruit.lua",["SHA256"]="42dd39be2189b9919424a014ce56a1d10f15c77a7bd7398c536993726b18907e",["Text"]="-----------------------------------\n-- ID: 5662\n-- Item: Dragon Fruit\n-- Food Effect: 5 Mins, All Races\n-----------------------------------\n-- Intelligence 4\n-- Agility -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.AGI, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dragon_heart.lua"]={["Path"]="scripts/items/dragon_heart.lua",["SHA256"]="564283fd4211702bbe871163d866717ddf6fa5d5c047bd4d8e3706908f947d82",["Text"]="-----------------------------------\n-- ID: 4486\n-- Item: Dragon Heart\n-- Food Effect: 5 minutes, Galka only\n-----------------------------------\n-- Strength: 7\n-- Intelligence: -9\n-- MP: -40\n-- HP: 40\n-- Demon Killer: 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_MEAT)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 5 * 60, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.INT, -9)\n    effect:addMod(xi.mod.FOOD_MP, -40)\n    effect:addMod(xi.mod.FOOD_HP, 40)\n    effect:addMod(xi.mod.DEMON_KILLER, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dragon_steak.lua"]={["Path"]="scripts/items/dragon_steak.lua",["SHA256"]="a12de56581c40aa4dec2a17da46e2d0741407eb9c6ff978d87771d3e6ee59524",["Text"]="-----------------------------------\n-- ID: 4350\n-- Item: dragon_steak\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Health 25\n-- Strength 7\n-- Intelligence -3\n-- Health Regen While Healing 2\n-- MP recovered while healing +2\n-- Attack % 20\n-- Attack Cap 150\n-- Ranged ATT % 20\n-- Ranged ATT Cap 150\n-- Demon Killer 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 150)\n    effect:addMod(xi.mod.FOOD_RATTP, 20)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 150)\n    effect:addMod(xi.mod.DEMON_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dragon_tank.lua"]={["Path"]="scripts/items/dragon_tank.lua",["SHA256"]="9c6080e099de48afdf5483b0c37ea1e55a3cbe0ab5b651e318ede33666d11af4",["Text"]="-----------------------------------\n-- ID: 11002\n-- Dragon Tank\n-- Dispense: Flask of Dragon Fruit au Lait\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_DRAGON_FRUIT_AU_LAIT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/dragoon_die.lua"]={["Path"]="scripts/items/dragoon_die.lua",["SHA256"]="b49fbe6b8e5c6f53d782b92e8f1212d302675fe0b97bcd4b5f05aef6d4976020",["Text"]="-----------------------------------\n-- ID: 5490\n-- Dragoon Die\n-- Teaches the job ability Drachen Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.DRACHEN_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.DRACHEN_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/dream_boots_+1.lua"]={["Path"]="scripts/items/dream_boots_+1.lua",["SHA256"]="81de73184f7c63aedf3823e9d186a07636a5d0d00ef11f1381cd0dcdc04fa962",["Text"]="-----------------------------------\n-- ID: 15753\n-- Item: Dream Boots +1\n-- Enchantment: Sneak\n-- Duration: 3 Mins 20 Secs\n-- TODO: Enhances duration of Sneak Effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.SNEAK) then\n        target:addStatusEffect(xi.effect.SNEAK, { power = 1, duration = math.floor(200 * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10 })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/dream_hat_+1.lua"]={["Path"]="scripts/items/dream_hat_+1.lua",["SHA256"]="603b98f21ed88481030ae6e5b00475fe8c80da8fbcfa4709fc552647a5b7d9f9",["Text"]="-----------------------------------\n-- ID: 15179\n-- Dream Hat +1\n-- Dispenses Ginger Cookies\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.GINGER_COOKIE, math.randomInt(1, 10) } })\nend\n\nreturn itemObject\n"},["scripts/items/dream_mittens_+1.lua"]={["Path"]="scripts/items/dream_mittens_+1.lua",["SHA256"]="6c10d4d4099a784094704e192eba158c05f9c30879a3477572d77c6b21963df1",["Text"]="-----------------------------------\n-- ID: 10383\n-- Item: Dream Mittens +1\n-- Enchantment: Invisible\n-- Duration: 3 Mins 20 Secs\n-- TODO: Enhances duration of Invisible Effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.INVISIBLE) then\n        target:addStatusEffect(xi.effect.INVISIBLE, { duration = math.floor(200 * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10 })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/dried_berry.lua"]={["Path"]="scripts/items/dried_berry.lua",["SHA256"]="0acfcc5e6a94c64b88ecc5a29102a3e311edcc0b8da513d0100980d7f8a88c32",["Text"]="-----------------------------------\n-- ID: 5672\n-- Item: dried_berry\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dried_date.lua"]={["Path"]="scripts/items/dried_date.lua",["SHA256"]="bda42d8c06611a582641bad5aee4bbff0bcc56313fb92aa57cc7f61e28717240",["Text"]="-----------------------------------\n-- ID: 5567\n-- Item: dried_date\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 10\n-- Magic 20\n-- Agility -1\n-- Intelligence 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dried_date_+1.lua"]={["Path"]="scripts/items/dried_date_+1.lua",["SHA256"]="fc609f099c9626eb1480cd0d9d99a82b337e726333742b2f0cdb2f8ba92a5423",["Text"]="-----------------------------------\n-- ID: 5574\n-- Item: dried_date_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 12\n-- Magic 22\n-- Agility -1\n-- Intelligence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 12)\n    effect:addMod(xi.mod.FOOD_MP, 22)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/drovers_belt.lua"]={["Path"]="scripts/items/drovers_belt.lua",["SHA256"]="578a8cd8c9fc45f2263c124e098c1d50203295de5ca56d062ea7ca56b62e6b5b",["Text"]="-----------------------------------\n-- ID: 15919\n-- Drover's Belt\n-- Enchantment: 60Min, Costume - Chigoe (red)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 1747, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/ducal_guards_ring.lua"]={["Path"]="scripts/items/ducal_guards_ring.lua",["SHA256"]="462fdda90aab3c8b22c4333d575ff702f0c46b50bd90aefd73a00c6bedf3d5c8",["Text"]="-----------------------------------\n-- ID: 14657\n-- Ducal Guard Ring\n-- Enchantment: \"Teleport-RuLude Gardens\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.RULUDE_GARDENS) then\n        result = 56\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.DUCALGUARD, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/duchy_earring.lua"]={["Path"]="scripts/items/duchy_earring.lua",["SHA256"]="e86558e3d4a6e558bf61f57e8b14a6ab30d593d2dedece9b51690b6d82d63c45",["Text"]="-----------------------------------\n-- ID: 16042\n-- Duchy Earring\n-- Enchantment: \"Teleport\" (Upper Jeuno)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.DUCHY_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/dune_gilet_+1.lua"]={["Path"]="scripts/items/dune_gilet_+1.lua",["SHA256"]="24882d8d0d624bc2838e3d5217bc1ce4bb211d01e4e660aea0dfdd63a1e262cb",["Text"]="-----------------------------------\n-- ID: 10271\n-- Dune Gilet +1\n-- Dispense: Berry Snowcone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERRY_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/duodecennial_ring.lua"]={["Path"]="scripts/items/duodecennial_ring.lua",["SHA256"]="849116075cd8d3e564d2618bf85f72699d53912c8f292ef952ea4eff32f18faa",["Text"]="-----------------------------------\n-- ID: 28562\n-- Item: Duodecennial Ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +100%\n-- Duration: 720 min\n-- Max bonus: 12000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 100\n    local duration  = 43200\n    local subpower  = 12000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/duplicatus_cell.lua"]={["Path"]="scripts/items/duplicatus_cell.lua",["SHA256"]="b3531b2f56ca6901fd1ecccefef3d704d2a545a4b3ac540bc08e3b560e120deb",["Text"]="-----------------------------------\n-- Duplicatus Cell\n-- ID 5373\n-- Unlocks support job\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.OBLIVISCENCE) then\n        return 0\n    end\n\n    return -1\nend\n\nitemObject.onItemUse = function(target)\n    target:delStatusEffectSilent(xi.effect.OBLIVISCENCE)\n    target:messageText(target, zones[target:getZoneID()].text.CELL_OFFSET + 8)\nend\n\nreturn itemObject\n"},["scripts/items/dusty_elixir.lua"]={["Path"]="scripts/items/dusty_elixir.lua",["SHA256"]="cdc8ac16722b6e78af270b90604730b9365c517420eddfb565688a9e2deb7df5",["Text"]="-----------------------------------\n-- ID: 5433\n-- Item: Dusty Elixir\n-- Item Effect: Instantly restores 25% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local mHP = target:getMaxHP()\n    local cHP = target:getHP()\n    local mMP = target:getMaxMP()\n    local cMP = target:getMP()\n\n    if mHP == cHP and mMP == cMP then\n        result = 56 -- Does not let player use item if their hp and mp are full\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP(target:getMaxHP() * .25)\n    target:addMP(target:getMaxMP() * .25)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/dusty_ether.lua"]={["Path"]="scripts/items/dusty_ether.lua",["SHA256"]="8619bacafab639dbeebd046e6262987ae7bcd98e4471551e2c37aa3bbc20e23a",["Text"]="-----------------------------------\n-- ID: 5432\n-- Item: Dusty Ether\n-- Item Effect: Instantly restores 150 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(150 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/dusty_potion.lua"]={["Path"]="scripts/items/dusty_potion.lua",["SHA256"]="f70de7550aed3abeb8e1fb480d69aaccd552d7748ccc4d9e67904f91e5340376",["Text"]="-----------------------------------\n-- ID: 5431\n-- Item: Dusty Potion\n-- Item Effect: Instantly restores 300 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(300 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/dusty_scroll_of_reraise.lua"]={["Path"]="scripts/items/dusty_scroll_of_reraise.lua",["SHA256"]="d5a90674671ede19b9116d72130b8b9d8ab738a4aa64915812a8c794d54215b6",["Text"]="-----------------------------------\n-- ID: 5436\n-- name: dusty_scroll_of_reraise\n-- effect: grants reraise III for 10m\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.RERAISE\n    local power     = 3\n    local duration  = 600\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/dusty_wing.lua"]={["Path"]="scripts/items/dusty_wing.lua",["SHA256"]="ba5ae2ed4304b4f3dcd414a6f1f6957b80b3458cce765d7a30d236d54730b406",["Text"]="-----------------------------------\n-- ID: 5440\n-- Dusty Wing\n-- Increases TP of the user by 3000\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(3000)\nend\n\nreturn itemObject\n"},["scripts/items/dweomer_bullet_pouch.lua"]={["Path"]="scripts/items/dweomer_bullet_pouch.lua",["SHA256"]="79aeb010a4ea4b37c6e556bca6b41c2ced6cd38321961f299d0c2792b925464b",["Text"]="-----------------------------------\n-- ID: 5822\n-- Dweomer Bullet Pouch\n-- When used, you will obtain one stack of Dweomer Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DWEOMER_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/ear_of_grilled_corn.lua"]={["Path"]="scripts/items/ear_of_grilled_corn.lua",["SHA256"]="e04d4d6d646a6d1e5e8f4082a2521a5cb9bbcb6211c988f86ed3c4ca1873e9ae",["Text"]="-----------------------------------\n-- ID: 4334\n-- Item: ear_of_grilled_corn\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 10\n-- Vitality 4\n-- Health Regen While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ear_of_roasted_corn.lua"]={["Path"]="scripts/items/ear_of_roasted_corn.lua",["SHA256"]="cd428c11c0cee9b1c2b2cba847330c43535f0f9d85bc65db66470d1994632666",["Text"]="-----------------------------------\n-- ID: 4415\n-- Item: ear_of_roasted_corn\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 6\n-- Dexterity -1\n-- Vitality 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 6)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.VIT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/earth_arrow.lua"]={["Path"]="scripts/items/earth_arrow.lua",["SHA256"]="d0d2a7575cbbd5dc722d97421459d969b0d15daf99d0c075cb7cb2785883a749",["Text"]="-----------------------------------\n-- ID: 18699\n-- Item: Earth Arrow\n-- Additional effect: Earth damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 10 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.EARTH,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/earth_card_case.lua"]={["Path"]="scripts/items/earth_card_case.lua",["SHA256"]="4c83c3934c7484c3504faad781297fd8ac04bf526ad0d656a495d3c8488ac0ed",["Text"]="-----------------------------------\n-- ID: 5405\n-- Earth Card Case\n-- When used, you will obtain one stack of Earth Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.EARTH_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/earth_cluster.lua"]={["Path"]="scripts/items/earth_cluster.lua",["SHA256"]="d32296fe087fdf024329587c092106b10f335618f72f2baf2258387a6c26b6f0",["Text"]="-----------------------------------\n-- ID: 4107\n-- Earth Cluster\n-- Turn into a stack of earth crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.EARTH_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/earth_spirit_pact.lua"]={["Path"]="scripts/items/earth_spirit_pact.lua",["SHA256"]="e2067b9265c4acc385eaaa0f4850e8f0527d53b3ca51d730e511254368566d3c",["Text"]="-----------------------------------\n-- ID: 4899\n-- Earth Spirit Pact\n-- Teaches the summoning magic Earth Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.EARTH_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.EARTH_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/earth_wand.lua"]={["Path"]="scripts/items/earth_wand.lua",["SHA256"]="886ad088abcf45f2e513bf0eb7d6a30a4e041d82eb65476a555e0182fb810f56",["Text"]="-----------------------------------\n-- ID: 17076\n-- Item: Earth Wand\n-- Additional effect: Earth damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 25 / 54, 0, 54), -- Linear interp\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.EARTH,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/eastern_san_doria_gate_glyph.lua"]={["Path"]="scripts/items/eastern_san_doria_gate_glyph.lua",["SHA256"]="2d7cc42dab003ad72cfa86dd8376faf39d3f4497fb6334cac984e0b2313872b6",["Text"]="-----------------------------------\n-- ID: 4190\n-- Eastern San d'Oria Gate Glyph\n-- Transports the user to the eastern Southern San d'oria gate\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.EAST_SANDY_GLYPH, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/echad_ring.lua"]={["Path"]="scripts/items/echad_ring.lua",["SHA256"]="8cc88f173a083818c5159a5ca4f708e96eff0c17b95970649d7a021e58972a85",["Text"]="-----------------------------------\n-- ID: 27556\n-- Item: echad ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +150%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 150\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/ecphoria_ring.lua"]={["Path"]="scripts/items/ecphoria_ring.lua",["SHA256"]="578fac0f99b04e5bf40a49f58ceba35a88b15cbed403c4092fc1cb7594a6e0d6",["Text"]="-----------------------------------\n-- ID: 15817\n-- Item: Ecphoria Ring\n-- Item Effect: This item remedies amnesia.\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local statusEffect = xi.effect.AMNESIA\n    if target:hasStatusEffect(statusEffect) then\n        local effectSubPower = target:getStatusEffect(statusEffect):getSubPower()\n        -- If the amnesia is too strong, do not remove it. By default this would be zero allowing removal.\n        -- (Ladybugs, Rafflesia, Promathia, certain NMs, low chance vs Disorienting Waul)\n        if effectSubPower < math.randomInt(1, 100) then\n            target:delStatusEffect(statusEffect)\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/eel_kabob.lua"]={["Path"]="scripts/items/eel_kabob.lua",["SHA256"]="557febdf157562e256094986a9c7a131fccbd7c1e999f994da3093df3e72d2e3",["Text"]="-----------------------------------\n-- ID: 4457\n-- Item: eel_kabob\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -3\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"}};
